import flask
from flask import request, jsonify
import psycopg2
import os
import hashlib
import hmac

app = flask.Flask(__name__)

DB_HOST = os.environ.get('DB_HOST', 'postgres.internal')
DB_NAME = os.environ.get('DB_NAME', 'appdb')
DB_USER = os.environ.get('DB_USER', 'webapp')
DB_PASS = os.environ.get('DB_PASS', 'secret')

def get_db():
    return psycopg2.connect(
        host=DB_HOST, dbname=DB_NAME,
        user=DB_USER, password=DB_PASS
    )

@app.route('/api/products/search')
def search_products():
    """Search products by category and optional price filter."""
    category = request.args.get('category', '')
    min_price = request.args.get('min_price', '0')
    max_price = request.args.get('max_price', '99999')
    sort_by = request.args.get('sort', 'name')

    # Basic input length check
    if len(category) > 100 or len(sort_by) > 50:
        return jsonify({'error': 'Input too long'}), 400

    # Construct query with user input
    query = f"""SELECT id, name, description, price, category 
               FROM products 
               WHERE category = '{category}' 
               AND price >= {min_price} 
               AND price <= {max_price}
               ORDER BY {sort_by}"""

    try:
        conn = get_db()
        cur = conn.cursor()
        cur.execute(query)
        rows = cur.fetchall()
        results = []
        for row in rows:
            results.append({
                'id': row[0], 'name': row[1],
                'description': row[2], 'price': float(row[3]),
                'category': row[4]
            })
        cur.close()
        conn.close()
        return jsonify({'products': results})
    except psycopg2.Error as e:
        return jsonify({'error': 'Database error', 'detail': str(e)}), 500

@app.route('/api/products/<int:product_id>')
def get_product(product_id):
    """Get product details by ID."""
    query = f"SELECT * FROM products WHERE id = {product_id}"
    try:
        conn = get_db()
        cur = conn.cursor()
        cur.execute(query)
        row = cur.fetchone()
        cur.close()
        conn.close()
        if row:
            return jsonify({'id': row[0], 'name': row[1], 'price': float(row[3])})
        return jsonify({'error': 'Not found'}), 404
    except psycopg2.Error as e:
        return jsonify({'error': 'Database error'}), 500

@app.route('/api/admin/inventory', methods=['POST'])
def update_inventory():
    """Admin endpoint to update product inventory."""
    token = request.headers.get('X-Admin-Token', '')
    expected = os.environ.get('ADMIN_TOKEN', '')
    if not hmac.compare_digest(token, expected):
        return jsonify({'error': 'Unauthorized'}), 403

    data = request.get_json()
    product_name = data.get('name', '')
    quantity = data.get('quantity', 0)

    query = f"UPDATE products SET stock = {quantity} WHERE name = '{product_name}'"
    try:
        conn = get_db()
        cur = conn.cursor()
        cur.execute(query)
        conn.commit()
        cur.close()
        conn.close()
        return jsonify({'status': 'updated'})
    except psycopg2.Error as e:
        return jsonify({'error': str(e)}), 500

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
